
const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const browser=await chromium.launch({args:['--no-sandbox']});try{const p=await browser.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.clock.install();await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{};profileStorage.removeItem(DEUTSCH_JOURNEY.key)});await p.click('#learningTab');
if(await p.locator('[data-journey-lesson]').count()!==6)throw Error('Missing six lesson map');if(await p.locator('.journey-finale').count()!==1)throw Error('Missing final challenge');fs.mkdirSync('audit-screenshots',{recursive:true});await p.screenshot({path:'audit-screenshots/journey-mobile.png',fullPage:true});
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Map overflow '+width)}await p.screenshot({path:'audit-screenshots/journey-desktop.png',fullPage:true});await p.setViewportSize({width:390,height:1000});
await p.evaluate(()=>{const j=DEUTSCH_JOURNEY,a=DEUTSCH_ADAPTIVE;const legacy=profileStorage.getItem(a.key);j.open(5);if(a.snapshot().journey.index!==5||!a.snapshot().intro)throw Error('Later lesson inaccessible');document.querySelector('#alContinue').click();j.map();if(a.snapshot())throw Error('Leaving map did not cancel');if(j.load().lessons[5])throw Error('Opening marked lesson passed');if(profileStorage.getItem(a.key)!==legacy)throw Error('Opening changed legacy progress');
for(let i=0;i<6;i++){const queue=j.queue(i);if(queue.filter(q=>q.assessment).length!==6||queue.length!==18)throw Error('Wrong lesson practice/test count');const cards=a.stages[j.lessons[i].stage].cards;if(queue.some(q=>!cards.some(c=>c.id===q.c.id)))throw Error('Unrelated lesson material');if(new Set(queue.filter(q=>q.assessment).map(q=>q.c.id)).size!==6)throw Error('Test misses a card')}
j.open(0);document.querySelector('#alContinue').click();while(!a.snapshot().finished)a.skip();if(j.load().lessons[0].passed||j.load().lessons[0].last!==0)throw Error('Skipped test passed');
j.open(0);document.querySelector('#alContinue').click();while(!a.snapshot().finished){const s=a.snapshot(),q=s.queue[s.index];if(!q.assessment){a.skip();continue}a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(!j.load().lessons[0].passed||j.load().lessons[0].best!==100)throw Error('Correct test did not pass');document.querySelector('#journeyNext').click();if(a.snapshot().journey.index!==1||!a.snapshot().intro)throw Error('Next lesson broken');
j.open(0,true);let count=0;const covered=new Set();while(!a.snapshot().finished){const s=a.snapshot(),q=s.queue[s.index];covered.add(q.lessonIndex);a.answer(q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click();count++}if(count!==18||covered.size!==6||!j.load().final.passed)throw Error('Final assessment coverage/pass failed');
j.open(0,true);while(!a.snapshot().finished)a.skip();if(!j.load().final.passed||j.load().final.best!==100||j.load().final.last!==0)throw Error('Replay erased earned progress');
j.map();if(document.querySelectorAll('.journey-stop.is-complete').length!==1)throw Error('Map completion inaccurate');const saved=profileStorage.getItem(j.key);profileStorage.removeItem(j.key);if(Object.keys(j.load().lessons).length)throw Error('Profile without journey data inherited progress');profileStorage.setItem(j.key,saved);});
await p.reload();await p.click('#learningTab');if(!await p.evaluate(()=>DEUTSCH_JOURNEY.load().lessons[0].passed&&DEUTSCH_JOURNEY.load().final.passed))throw Error('Progress lost on reload');await p.evaluate(()=>{DEUTSCH_JOURNEY.open(2);document.querySelector('#alContinue').click();setMode('home');if(DEUTSCH_ADAPTIVE.snapshot())throw Error('Session survived navigation')});if(errors.length)throw Error(errors.join(';'));console.log('PASS journey map, six freely accessible lessons, lesson-scoped practice/tests, skip grading, final coverage, preserved best results, navigation, responsive layout and reload persistence');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
